import {esc,num,panel,chart,table} from './ui.mjs';
import {summarize,histogram,perWellMetrics,ROLE_NAMES,METRIC_INFO,PERCENT_METRICS} from './evaluation.mjs';
import {finite} from '../agent/core.mjs';
export const ROLE_COLORS={train:'#a92b38',validation:'#b58e51',test:'#4a80ac'};
export function formatMetric(key,value){if(value===null||value===undefined||!Number.isFinite(Number(value)))return '—';return PERCENT_METRICS.has(key)?num(value*100,2)+'%':num(value,['N','LabelN','MAPE_N'].includes(key)?0:4)+(key==='MAPE'||key==='sMAPE'?'%':'');}
function box(title,body,note=''){return `<section class="analysis-chart"><h3>${title}</h3>${body}${note?`<p class="tiny">${note}</p>`:''}</section>`;}
export function barChart(items,{unit='',label='类别',color='#a92b38'}={}){const valid=items.filter(r=>finite(r.value));if(!valid.length)return '<div class="empty">当前数据不足以计算此图</div>';const lo=Math.min(0,...valid.map(r=>r.value)),hi=Math.max(0,...valid.map(r=>r.value)),span=hi-lo||1,w=640,h=230,top=23,bottom=53,left=57,right=15,plotH=h-top-bottom,plotW=w-left-right,zero=top+(hi/span)*plotH,barW=Math.min(55,plotW/valid.length*.58),y=v=>top+(hi-v)/span*plotH;return `<div class="analysis-svg"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)}柱状图；${esc(unit)}"><text x="${left}" y="12">${esc(unit)}</text>${[0,1,2,3,4].map(i=>{const v=lo+span*i/4;return `<line x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}" stroke="#e9e6df"/><text x="${left-8}" y="${y(v)+4}" text-anchor="end">${num(v,span<5?2:0)}</text>`;}).join('')}${valid.map((r,i)=>{const x=left+plotW*(i+.5)/valid.length;return `<g><title>${esc(r.label)}：${num(r.value,4)} ${esc(unit)}</title><rect x="${x-barW/2}" y="${Math.min(y(r.value),zero)}" width="${barW}" height="${Math.max(.8,Math.abs(y(r.value)-zero))}" rx="2" fill="${r.color??color}"/><text x="${x}" y="${r.value>=0?y(r.value)-6:y(r.value)+14}" text-anchor="middle">${num(r.value,span<5?3:1)}</text><text x="${x}" y="${h-30}" text-anchor="middle">${esc(String(r.label).length>15?String(r.label).slice(0,14)+'…':r.label)}</text></g>`;}).join('')}<text x="${w/2}" y="${h-6}" text-anchor="middle">${esc(label)}</text></svg></div>`;}
function scatter(points,unit){if(!points.length)return '<div class="empty">没有同时具备真实值和预测值的记录</div>';const values=points.flatMap(r=>[r.actual,r.prediction]);let lo=values.reduce((a,v)=>Math.min(a,v),Infinity),hi=values.reduce((a,v)=>Math.max(a,v),-Infinity);if(lo===hi){lo-=1;hi+=1;}const pad=(hi-lo)*.06;lo-=pad;hi+=pad;const w=640,h=270,l=65,t=25,b=47,r=20,x=v=>l+(v-lo)/(hi-lo)*(w-l-r),y=v=>t+(hi-v)/(hi-lo)*(h-t-b),stride=Math.max(1,Math.ceil(points.length/400));return `<div class="analysis-svg"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="真实值与预测值散点图；对角线为理想预测">${[0,1,2,3,4].map(i=>{const v=lo+(hi-lo)*i/4;return `<line x1="${l}" x2="${w-r}" y1="${y(v)}" y2="${y(v)}" stroke="#ece8e1"/><text x="${l-8}" y="${y(v)+4}" text-anchor="end">${num(v,hi-lo<5?2:0)}</text><text x="${x(v)}" y="${h-29}" text-anchor="middle">${num(v,hi-lo<5?2:0)}</text>`;}).join('')}<path d="M${x(lo)} ${y(lo)}L${x(hi)} ${y(hi)}" stroke="#bba784" stroke-dasharray="5 4"/>${points.filter((_,i)=>i%stride===0).map(r=>`<circle cx="${x(r.actual)}" cy="${y(r.prediction)}" r="3" fill="#a92b38" fill-opacity=".55"><title>真实${num(r.actual)}，预测${num(r.prediction)}</title></circle>`).join('')}<text x="${l}" y="13">预测值 / ${esc(unit)}</text><text x="${w/2}" y="${h-6}" text-anchor="middle">真实值 / ${esc(unit)} · 金色虚线：预测=真实</text></svg></div>`;}
function confusionView(confusion){if(!confusion)return '<div class="empty">缺少真实类别，不能生成混淆矩阵</div>';const {labels,matrix}=confusion;return `<div class="confusion-wrap"><table class="confusion"><thead><tr><th>真实 ↓ / 预测 →</th>${labels.map(l=>`<th>${esc(l)}</th>`).join('')}</tr></thead><tbody>${labels.map((l,i)=>{const n=matrix[i].reduce((s,v)=>s+v,0);return `<tr><th>${esc(l)}</th>${matrix[i].map((v,j)=>`<td style="background:${i===j?`rgba(47,126,105,${.08+(n?v/n:0)*.62})`:`rgba(174,46,55,${.04+(n?v/n:0)*.5})`}"><b>${v}</b><small>${n?num(100*v/n,1)+'%':'—'}</small></td>`).join('')}</tr>`;}).join('')}</tbody></table></div><p class="tiny">单元格：样本数及该真实类别内的百分比；绿色对角线为正确分类，红色为误分。未知真实类别也计入评价。</p>`;}
function rocView(roc){if(!roc)return '<div class="empty">ROC需要连续异常评分和正负真实标签；当前不具备</div>';const w=460,h=240,l=45,t=20,b=36,r=20,x=v=>l+v*(w-l-r),y=v=>t+(1-v)*(h-t-b);return `<div class="analysis-svg"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="ROC曲线，AUC ${num(roc.auc,4)}"><path d="M${x(0)} ${y(0)}L${x(1)} ${y(1)}" stroke="#baab92" stroke-dasharray="5 4"/><path d="${roc.curve.map((p,i)=>(i?'L':'M')+x(p.fpr)+','+y(p.tpr)).join(' ')}" stroke="#ac2936" fill="none" stroke-width="2"/><text x="${l}" y="13">召回率 TPR</text><text x="${w/2}" y="${h-5}" text-anchor="middle">误报率 FPR（0–1） · AUC=${num(roc.auc,4)}</text><text x="${l-10}" y="${y(0)+4}">0</text><text x="${l-10}" y="${y(1)+4}">1</text><text x="${x(1)}" y="${h-21}">1</text></svg></div>`;}
function emptySummary(s){return '<div class="empty">训练后自动计算训练、验证、测试三组结果；没有真实值时仍保留模型输出，不生成评价指标。</div>';}
export function comparisonView(m,s){const entries=Object.entries(s.summaries??{});if(!entries.length)return emptySummary(s);const kind=entries.find(([,v])=>v)?.[1].kind??'regression',keys=kind==='regression'?['N','MAE','RMSE','R2','MAPE','sMAPE','Bias']:kind==='multilabel'?['N','ExactMatch','Precision','Recall','F1','HammingLoss']:['N','Accuracy','Precision','Recall','F1','AUC'];return `<div class="results-heading"><h3>训练 / 验证 / 测试 · 并列评价</h3><button class="btn small" data-studio="evaluation-export">↓ 三组指标与完整结果</button></div><div class="evaluation-table"><table><thead><tr><th>数据集</th><th>输入/输出/有效评价</th><th>预测覆盖率</th>${keys.filter(k=>k!=='N').map(k=>`<th>${METRIC_INFO[k]?.[0]??k}<br><small>${k}</small></th>`).join('')}</tr></thead><tbody>${['train','validation','test'].map(role=>{const a=s.summaries[role];if(!a)return `<tr><td>${ROLE_NAMES[role]}</td><td colspan="${keys.length+1}">${esc(s.evaluationErrors?.[role]??'等待计算')}</td></tr>`;return `<tr><td><i class="role-dot" style="background:${ROLE_COLORS[role]}"></i>${ROLE_NAMES[role]}</td><td>${a.inputCount} / ${a.predicted} / ${a.metrics?.N??0}</td><td>${num(a.coverage,1)}%</td>${keys.filter(k=>k!=='N').map(k=>`<td>${formatMetric(k,a.metrics?.[k])}</td>`).join('')}</tr>`;}).join('')}</tbody></table></div><div class="note">训练集为样本内拟合表现；验证集用于监测；测试集为当前固定模型的独立评价，不据测试分数自动选模。MAPE排除真实值接近0的记录，R²在真实值恒定时不定义。预测覆盖率分母为该组输入行数。</div><div class="grid equal">${kind==='regression'?['MAE','RMSE'].map(key=>box(METRIC_INFO[key][0]+' · 三组对比',barChart(entries.map(([role,a])=>({label:ROLE_NAMES[role],value:a.metrics?.[key],color:ROLE_COLORS[role]})),{unit:m.unit,label:'数据集'}))).join(''):['Accuracy','F1'].filter(k=>kind!=='multilabel'||k!=='Accuracy').map(key=>box(METRIC_INFO[key][0]+' · 三组对比',barChart(entries.map(([role,a])=>({label:ROLE_NAMES[role],value:a.metrics?.[key]===undefined?null:a.metrics[key]*100,color:ROLE_COLORS[role]})),{unit:'%',label:'数据集'}))).join('')}</div><div class="three set-result-curves">${entries.map(([role,a])=>{const w=a.rows[0]?.test_id??a.rows[0]?.well_id,rs=a.rows.filter(r=>(r.test_id??r.well_id)===w).slice(-60);return box(ROLE_NAMES[role]+' · '+esc(w??'样本'),kind==='regression'?chart([{name:'真实值',values:rs.map(r=>r.actual),labels:rs.map(r=>r.date??r.sample_id??r.time_days),color:ROLE_COLORS[role]},{name:'预测值',values:rs.map(r=>r.prediction),color:'#313d49',dash:true}],{unit:m.unit}):barChart(a.perClass.map(c=>({label:c.label,value:c.f1*100,color:ROLE_COLORS[role]})),{unit:'F1 / %',label:'真实/预测类别'}),kind==='regression'?'每组预览首口井；可在下方切换具体对象。':'不把类别编号当作连续产量画折线。');}).join('')}</div><details class="metric-guide"><summary>评价指标公式、单位与含义</summary><div class="data-table">${table(Object.entries(METRIC_INFO).filter(([k])=>keys.includes(k)||kind==='regression'&&['MSE','MaxAE','MAPE_N'].includes(k)).map(([k,[n,f,u]])=>({k,n,f,u})),[['k','指标'],['n','中文含义'],['f','计算公式'],['u','单位 / 说明']],30)}</div></details>`;}
export function detailView(m,s){const role=s.detailRole??'test',summary=s.summaries?.[role],output=s.resultSource==='calc'?s.results:summary?.rows??s.results??[],kind=s.resultSource==='calc'?summarize(m,output).kind:summary?.kind??summarize(m,output).kind;const wells=[...new Set(output.map(r=>r.test_id??r.well_id??'未指定'))];const selected=wells.includes(s.detailWell)?s.detailWell:wells[0],rows=output.filter(r=>(r.test_id??r.well_id??'未指定')===selected),a=summarize(m,rows,rows.length),regression=kind==='regression';return `<div class="results-heading"><h3>${s.resultSource==='calc'?'计算输入预测结果':'各数据集预测结果与诊断'}</h3><button class="btn small" data-studio="results" ${!output.length?'disabled':''}>↓ 当前完整结果CSV</button></div><div class="row" style="margin:15px 0">${s.resultSource==='calc'?'':`<label>结果数据集 <select id="result-role" data-studio-change="role">${Object.entries(ROLE_NAMES).map(([v,n])=>`<option value="${v}" ${v===role?'selected':''}>${n}</option>`).join('')}</select></label>`}<label>结果对象 <select id="result-well" data-studio-change="well">${wells.map(w=>`<option ${w===selected?'selected':''}>${esc(w)}</option>`).join('')}</select></label><span class="tag">${output.length}条输出 · 当前对象${rows.length}条</span></div>${!output.length?'<div class="empty">训练后自动生成三组结果；或上传计算输入运行模型</div>':regression?regressionView(m,rows,a,output):classificationView(m,rows,a)}${output.length?`<div class="results-heading"><h3>逐条预测与误差明细</h3><span class="tiny">预览当前对象前30条；导出包含当前数据集全部对象</span></div>${table(rows.map(r=>({...r,time:r.date??r.sample_id??r.time_days??r.event_id,absError:finite(r.actual)&&finite(r.prediction)&&regression?Math.abs(Number(r.prediction)-Number(r.actual)):null,error:finite(r.actual)&&finite(r.prediction)&&regression?Number(r.prediction)-Number(r.actual):null})),[['well_id','井/对象'],['time','时间/样本'],['actual','真实值/标签'],['prediction','预测值/类别'],['error','误差（预测−真实）'],['absError','绝对误差'],['score','异常评分']],30)}`:''}`;}
function regressionView(m,rows,a,all){const data=rows.slice(-150),labels=data.map(r=>r.date??r.sample_id??r.time_days??r.log_horner),pairs=a.evaluated??[],hist=histogram(pairs.map(r=>r.error),10),perWell=perWellMetrics(m,all);return `<div class="grid equal">${box('真实值与预测值',chart([{name:'真实观测',values:data.map(r=>r.actual),labels,color:'#b58e51'},{name:'模型预测',values:data.map(r=>r.prediction),color:'#a92b38',dash:true}],{unit:m.unit}),'仅连接同一对象，最多预览末150条。')}${box('预测一致性散点图',scatter(pairs,m.unit),'金色对角线为理想预测；散点最多显示400条，指标使用全部有效记录。')}${box('残差随样本变化',chart([{name:'预测−真实',values:pairs.slice(-150).map(r=>r.error),labels:pairs.slice(-150).map(r=>r.date??r.sample_id),color:'#4a80ac'},{name:'零误差参考线',values:pairs.slice(-150).map(()=>0),color:'#b58e51',dash:true}],{unit:m.unit}),'正残差为高估，负残差为低估。')}${box('残差分布直方图',barChart(hist.map(r=>({label:num((r.left+r.right)/2,1),value:r.count,color:r.left+r.right<0?'#4a80ac':'#a92b38'})),{unit:'样本数 / 条',label:'残差分箱中心（'+m.unit+'）'}),'分箱使用当前对象全部有效残差，柱高为样本数。')}</div>${box('各井 / 对象预测误差',barChart(perWell.filter(r=>r.RMSE!==undefined).slice(0,20).map(r=>({label:r.well,value:r.RMSE,color:'#b58e51'})),{unit:'RMSE / '+m.unit,label:'井 / 对象'}),'与当前结果数据集一致；最多展示20个对象。')}`;}
function classificationView(m,rows,a){return `<div class="grid equal">${box(a.kind==='multilabel'?'逐标签识别表现':'分类混淆矩阵',a.kind==='multilabel'?barChart(a.perClass.map(r=>({label:r.label,value:r.f1*100})),{unit:'F1 / %',label:'诊断标签'}):confusionView(a.confusion))}${box('各类别精确率 / 召回率',barChart(a.perClass.flatMap(r=>[{label:r.label+'精确率',value:r.precision*100,color:'#a92b38'},{label:r.label+'召回率',value:r.recall*100,color:'#4a80ac'}]),{unit:'%',label:'类别与指标'}))}</div>${rows.some(r=>finite(r.score))?`<div class="grid equal">${box('异常评分与真实/预测标签',chart([{name:'异常评分',values:rows.map(r=>r.score),color:'#a92b38',labels:rows.map(r=>r.date??r.sample_id)}],{unit:'无量纲异常分数'}))}${box('ROC曲线',rocView(a.roc))}</div>`:''}${table(a.perClass.map(r=>({...r,precision:100*r.precision,recall:100*r.recall,f1:100*r.f1})),[['label','类别/标签'],['support','真实样本数'],['precision','精确率（%）'],['recall','召回率（%）'],['f1','F1（%）'],['tp','TP'],['fp','FP'],['fn','FN']],30)}${!a.metrics?'<div class="note">本批无真实标签，已显示模型输出与评分，不能计算准确率、F1或混淆矩阵。</div>':''}`;}
